<?phpnamespace app\api\controller;use app\api\model\User as UserModel;use app\api\model\WechatBatchSend as WechatBatchSendModel;use app\api\model\Keyword as KeywordModel;use app\api\model\Setting;use hema\wechat\Wechat as Wx;use think\facade\Cache;use think\facade\Session;use addons\wxlogin\library\Wxlogin as Wxweb;/** * 平台网关通讯接口 */class Task extends \app\BaseController{    protected $config;    //平台应用配置        /**     * 支付宝消息与事件接收通知处理     */    public function alipay()    {        //接收消息		$msg = file_get_contents ('php://input');		parse_str($msg,$data);    }    /**     * 微信扫码登录     */    public function wxlogin(string $code = '',string $state = '')    {    	$wx = new Wxweb;    	//通过code获取access_token        $result = $wx->getToken($code);	    if(!$result){	    	die(json_encode(['code' => 0, 'msg' => '获取access_token失败'],JSON_UNESCAPED_UNICODE));	    }	    if(!$user = $result['user_model']::where(['union_id' => $result['unionid']])->find()){	        //新增用户			$model = new $result['user_model'];			$data = [	    		'union_id' => $result['unionid'],			];			$model->add($data);			$user = $result['user_model']::where(['union_id' => $result['unionid']])->find();		}        // 保存登录状态        Session::set('hema_' . $result['redirect_uri'], [            'user' => $user->toArray(),            'is_login' => true,        ]);        return redirect('/' . $result['redirect_uri']);	}    /**     * 微信消息与事件接收通知处理     */    public function wechat(string $appid = '')    {        if(config('app.hemaphp.system') == 'saas'){            if(!empty($appid)){        	    $this->config = WechatModel::getWechat(['app_id' => $appid]);        	}    		// 接收公众号平台发送的消息    		$nonce = empty ( $_GET ['nonce'] ) ?"" : trim ( $_GET ['nonce'] );    		$signature = empty ( $_GET['signature'] ) ? "" : trim ( $_GET ['signature'] );    		$timeStamp = empty ( $_GET ['timestamp']) ? "" : trim ( $_GET ['timestamp'] );    		$msg_signature = empty ( $_GET['msg_signature'] ) ? "" : trim ( $_GET ['msg_signature'] );    		$encryptMsg = file_get_contents ('php://input' );    		$pc = new WxBizMsgCrypt;//创建解密类    		$msg = '';		    		$errCode = $pc->decryptMsg($msg_signature, $timeStamp, $nonce, $encryptMsg, $msg);	    		if($errCode == 0){    			$data = _xml_to_arr($msg);	//XML转换为数组    			//write_log($data, __DIR__);    			$this->wechatHandle($data);    		}else{    			write_log('Wechat 解密失败 - 错误代码：'.$errCode, __DIR__);    		}        }else{            //接收效验参数            $signature = empty ( $_GET ['signature'] ) ?"" : trim ( $_GET ['signature'] );            $timestamp = empty ( $_GET ['timestamp'] ) ?"" : trim ( $_GET ['timestamp'] );            $nonce = empty ( $_GET ['nonce'] ) ?"" : trim ( $_GET ['nonce'] );            //接收消息    		$msg = file_get_contents ('php://input' );    		$data = _xml_to_arr($msg);	//XML转换为数组    		//write_log($data,__DIR__);                //验证是否来自微信平台            $this->config = Setting::getItem('wechat');            $token = $this->config['token'];            $tmpArr = array($token, $timestamp, $nonce);            sort($tmpArr, SORT_STRING);            $tmpStr = implode($tmpArr );            $tmpStr = sha1( $tmpStr );            if( $tmpStr == $signature ){                //来自微信平台                $this->wechatHandle($data);            }else{                //非法数据                write_log('非法请求',__DIR__);            }        }    }        /**     * 公众号消息与时间处理    */	private function wechatHandle(array $data)	{        if(isset($data['MsgType'])){            //事件			if($data['MsgType']=='event'){			    //用户未关注时，进行关注后的事件推送			    if($data['Event']=='subscribe'){			        if(config('app.hemaphp.system') == 'saas'){    			        $data['applet_id'] = $this->config['applet_id'];    			        $subscribe = Setting::getItem('subscribe',$this->config['applet_id']);    			    }else{    			        $subscribe = Setting::getItem('subscribe');    			    }			        $model = new UserModel;			        $model->subscribe($data);			        //判断是否为扫码关注（登录操作）			        if(isset($data['Ticket']) and $data['EventKey'] == 'qrscene_login'){                       $this->scanLogin($data);                    }			        //是否设置了关注回复					if($subscribe){						$this->replyMsg($subscribe,$data);//回复信息					}			    }			    //取消关注事件			    if($data['Event']=='unsubscribe'){			        $model = new UserModel;			        $model->unsubscribe($data);			    }			    //扫描带参数二维码事件 - 用户已关注时的事件推送				if($data['Event']=='SCAN'){				    //判断是否为扫码关注（登录操作）				    if(isset($data['Ticket']) and $data['EventKey'] == 'login'){				        $this->scanLogin($data);                    }				}				//自定义菜单事件 - 点击菜单拉取消息时的事件推送				if($data['Event']=='CLICK'){					//判断是否来自公众号菜单并携带关键字            		if(isset($data['EventKey']) AND !empty($data['EventKey'])){            			$data['Content'] = $data['EventKey'];            			$data['MsgType'] = 'text';            			$this->textMsg($data);            		}				}				//群发任务回调事件推送				if($data['Event']=='MASSSENDJOBFINISH'){					$msg = WechatBatchSendModel::getSend($data['MsgID']);					$msg->backEdit($data);				}				//上报地理位置事件				if($data['Event']=='LOCATION'){}				//自定义菜单事件 - 点击菜单跳转链接时的事件推送				if($data['Event']=='VIEW'){}				//添加附近门店类目审核回调				if($data['Event']=='nearby_category_audit_info'){					//$this->nearby_category_audit_info($data);				}				//添加附近小程序地点审核回调				if($data['Event']=='add_nearby_poi_audit_info'){					write_log('添加附近小程序地点审核回调',__DIR__);				}				//代码审核失败结果推送                if($data['Event'] == 'weapp_audit_fail'){}                //代码审核延后推送                if($data['Event'] == 'weapp_audit_delay'){}                //代码审核成功结果推送				if($data['Event'] == 'weapp_audit_success'){				    $values = Setting::getItem('other');				    //验证是否设置了自动上线				    if($values['applet_online'] == 1){    					//获取商户数据    					if($applet = AppletModel::getApplet(['user_name' => $data['ToUserName']])){                             $wx = new Wxapp(true,$applet['applet_id']);    					    $wx->release();//发布已通过审核的小程序    					}				    }				}                //名称审核结果事件推送                if($data['Event'] == 'wxa_nickname_audit'){                    if($applet = AppletModel::getApplet([						'user_name' => $data['ToUserName']					])){                         if($name = AppletNameModel::getAppletName(['nick_name' => $data['nickname'],'applet_id' => $applet['applet_id'],'status' => 0])){                            //成功                            if($data['ret']==3){                                $name->save(['status' => 1]);                                $applet->save(['app_name' => $data['nickname']]);                            }                            //失败                            if($data['ret']==2){                                $name->save(['status' => 2,'reason' => $data['reason']]);                                $applet->save(['app_name' => $data['nickname'] . '->被拒绝：'.$data['reason']]);                            }                        }                    }                }			}			            //消息			//接收普通消息 - 文本消息			if($data['MsgType']=='text'){				$this->textMsg($data);//文本消息处理			}			//接收普通消息 - 图片消息			if($data['MsgType']=='image'){				//发什么回什么				echo $this->msgTpl([					'ToUserName' => $data['FromUserName'],					'FromUserName' => $data['ToUserName'],					'MsgType' => $data['MsgType'],					'MediaId' => $data['MediaId']				]);			}			//接收普通消息 - 语音消息			if($data['MsgType']=='voice'){				//发什么回什么				echo $this->msgTpl([					'ToUserName' => $data['FromUserName'],					'FromUserName' => $data['ToUserName'],					'MsgType' => $data['MsgType'],					'MediaId' => $data['MediaId']				]);			}			//接收普通消息 - 视频消息			if($data['MsgType']=='video'){				//发什么回什么				echo $this->msgTpl([					'ToUserName' => $data['FromUserName'],					'FromUserName' => $data['ToUserName'],					'MsgType' => 'text',					'Content' => '我不看，太低俗~'				]);			}			//接收普通消息 - 小视频消息			if($data['MsgType']=='shortvideo'){}			//接收普通消息 - 地理位置消息			if($data['MsgType']=='location'){}			//接收普通消息 - 链接消息			if($data['MsgType']=='link'){}            die('success');//5秒内不回复'success',用户端会显示'该公众号暂时无法提供服务，请稍后再试'        }    }    /**     * 扫码关注公众号登录处理     */    private function scanLogin(array $data)    {        if(config('app.hemaphp.system') == 'saas'){            $wx = new Wx(true,$this->config['applet_id']);        }else{	        $wx = new Wx;        }        if($result = $wx->getUserInfo($data['FromUserName'])){            Cache::set($data['Ticket'],$result,180);//缓存3分钟	    }    }        /**     * 用于验证token     */    public function token()    {        $token = '';//填写你要验证的Token                //接收效验参数        $signature = empty ( $_GET ['signature'] ) ?"" : trim ( $_GET ['signature'] );        $timestamp = empty ( $_GET ['timestamp'] ) ?"" : trim ( $_GET ['timestamp'] );        $nonce = empty ( $_GET ['nonce'] ) ?"" : trim ( $_GET ['nonce'] );        $echostr = empty ( $_GET ['echostr'] ) ?"" : trim ( $_GET ['echostr'] );        $tmpArr = array($token, $timestamp, $nonce);        sort($tmpArr, SORT_STRING);        $tmpStr = implode($tmpArr );        $tmpStr = sha1( $tmpStr );       if( $tmpStr == $signature ){            die($echostr);        }else{            die($token);        }    }        /**     * 处理文本消息    */	private function textMsg(array $data)	{		//是否设置了关键字回复		switch($data['Content']){			case 'id':				echo $this->msgTpl([						'ToUserName' => $data['FromUserName'],						'FromUserName' => $data['ToUserName'],						'MsgType' => 'text',						'Content' => $data['FromUserName']					]);				break;			default:				if($values = KeywordModel::getKeys($data['Content'])->toArray()){					$this->replyMsg($values,$data);//回复信息				}else{					if($values = KeywordModel::getKeys('*')->toArray()){						$this->replyMsg($values,$data);//回复信息					}else{						//没有，发什么回什么						echo $this->msgTpl([							'ToUserName' => $data['FromUserName'],							'FromUserName' => $data['ToUserName'],							'MsgType' => $data['MsgType'],							'Content' => $data['Content']						]);					}				}		}	}        /**     * 被动回复用户消息    */	private function replyMsg(array $msg,array $data)	{		//是否开启		if($msg['is_open']['value']==1){			//文字消息			if($msg['type']['value']=='text'){				echo $this->msgTpl([					'ToUserName' => $data['FromUserName'],					'FromUserName' => $data['ToUserName'],					'MsgType' => 'text',					'Content' => $msg['content']['text']				]);			}						//图片消息			if($msg['type']['value']=='image'){				echo $this->msgTpl([				  'ToUserName' => $data['FromUserName'],				  'FromUserName' => $data['ToUserName'],				  'MsgType' => 'image',				  'MediaId' => $msg['content']['media_id']				]);			}			//语音消息			if($msg['type']['value']=='voice'){				echo $this->msgTpl([				  'ToUserName' => $data['FromUserName'],				  'FromUserName' => $data['ToUserName'],				  'MsgType' => 'voice',				  'MediaId' => $msg['content']['media_id']				]);			}			//视频消息			if($msg['type']['value']=='video'){				echo $this->msgTpl([				  'ToUserName' => $data['FromUserName'],				  'FromUserName' => $data['ToUserName'],				  'MsgType' => 'video',				  'Title' => $msg['content']['title'],				  'Description' => $msg['content']['description'],				  'MediaId' => $msg['content']['media_id']				]);				}			/*			//音乐消息			if($msg['type']['value']=='music'){				echo $this->msgTpl([				  'ToUserName' => $data['FromUserName'],				  'FromUserName' => $data['ToUserName'],				  'MsgType' => 'music',				  'Title' => $msg['content']['title'],				  'Description' => $msg['content']['description'],				  'MusicUrl' => $msg['content']['url'],				  'HQMusicUrl' => $msg['content']['hurl'],				  'ThumbMediaId' => $msg['content']['media_id']				]);			}*/			//图文消息			if($msg['type']['value']=='news'){				echo $this->msgTpl([				  'ToUserName' => $data['FromUserName'],				  'FromUserName' => $data['ToUserName'],				  'MsgType' => 'news',				  'ArticleCount' => $msg['content']['article_count'],				  'Articles' => $msg['content']['articles']				]);			}		}	}		/**     * 将array转为xml    */	private function msgTpl(array $arr)	{		$xml ="<xml><ToUserName><![CDATA[" . $arr['ToUserName'] . "]]></ToUserName>";		$xml .="<FromUserName><![CDATA[" . $arr['FromUserName'] . "]]></FromUserName>";		$xml .="<CreateTime>" . time() . "</CreateTime>";		$xml .="<MsgType><![CDATA[" . $arr['MsgType'] . "]]></MsgType>";		switch($arr['MsgType']){			case "text":				$xml .="<Content><![CDATA[" . $arr['Content'] . "]]></Content>";				break;			case "image":				$xml .= "<Image><MediaId><![CDATA[" . $arr['MediaId'] . "]]></MediaId></Image>";				break;			case "voice":				$xml .= "<Voice><MediaId><![CDATA[" . $arr['MediaId'] . "]]></MediaId></Voice>";				break;			case "video":				$xml .= "<Video><MediaId><![CDATA[" . $arr['MediaId'] . "]]></MediaId><Title><![CDATA[" . $arr['Title'] . "]]></Title><Description><![CDATA[" . $arr['Description'] . "]]></Description></Video>";				break;			case "music":				$xml .= "<Music><Title><![CDATA[" . $arr['Title'] . "]]></Title><Description><![CDATA[" . $arr['Description'] . "]]></Description><MusicUrl><![CDATA[" . $arr['MusicUrl'] . "]]></MusicUrl><HQMusicUrl><![CDATA[" . $arr['HQMusicUrl'] . "]]></HQMusicUrl><ThumbMediaId><![CDATA[" . $arr['ThumbMediaId'] . "]]></ThumbMediaId></Music>";				break;			case "news":				$xml .= "<ArticleCount>".$arr['ArticleCount']."</ArticleCount><Articles>";                     foreach ($arr['Articles'] as $vo){            				$xml .= "<item><Title><![CDATA[". $vo['title'] ."]]></Title><Description><![CDATA[". $vo['description'] ."]]></Description><PicUrl><![CDATA[". $vo['pic_url'] ."]]></PicUrl><Url><![CDATA[". $vo['url'] ."]]></Url></item>";                    }				$xml .= "</Articles>";				break;		}		$xml .= "</xml>";		return $xml;	}	}